package io.github.m08ij.salamacademy;

import android.content.Context;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Calendar;
import org.json.JSONArray;
import org.json.JSONObject;

/**
 * The Salam values catalog bundled in the APK (assets/catalog.json, generated by tools/make-catalog.js),
 * so the "Value of the day" widget works offline and without signing in.
 */
public final class Catalog {
    private static JSONArray values;
    private Catalog() {}

    public static final class Value {
        public String title = "", relation = "", balance = "", excess = "", deficit = "", behavior = "";
        public int relationId = 0, index = 0, count = 0;
    }

    private static synchronized JSONArray load(Context c) {
        if (values != null) return values;
        try (InputStream in = c.getAssets().open("catalog.json")) {
            byte[] b = new byte[in.available()];
            int off = 0, n;
            while (off < b.length && (n = in.read(b, off, b.length - off)) > 0) off += n;
            values = new JSONObject(new String(b, 0, off, StandardCharsets.UTF_8)).getJSONArray("values");
        } catch (Exception e) { values = new JSONArray(); }
        return values;
    }

    /** Today as yyyymmdd in the device's time zone. */
    public static int today() {
        Calendar k = Calendar.getInstance();
        return k.get(Calendar.YEAR) * 10000 + (k.get(Calendar.MONTH) + 1) * 100 + k.get(Calendar.DAY_OF_MONTH);
    }

    /** Stable "day number" so every user sees the same value on the same date. */
    static int dayNumber() {
        Calendar k = Calendar.getInstance();
        long local = k.getTimeInMillis() + k.get(Calendar.ZONE_OFFSET) + k.get(Calendar.DST_OFFSET);
        return (int) (local / 86400000L);
    }

    public static Value ofTheDay(Context c, String lang) {
        JSONArray a = load(c);
        Value v = new Value();
        v.count = a.length();
        if (v.count == 0) return v;
        int shift = WidgetStore.valueShift(c, today());
        // 37 is coprime with the catalog size in practice, so consecutive days jump across relations instead of walking in order.
        int idx = (int) (((long) (dayNumber() + shift) * 37L) % v.count);
        if (idx < 0) idx += v.count;
        v.index = idx;
        int L = "en".equals(lang) ? 1 : 0;
        try {
            JSONObject o = a.getJSONObject(idx);
            v.title = pick(o.optJSONArray("t"), L);
            v.relationId = o.optInt("r", 0);
            v.balance = pick(o.optJSONArray("b"), L);
            v.excess = pick(o.optJSONArray("x"), L);
            v.deficit = pick(o.optJSONArray("l"), L);
            JSONArray beh = o.optJSONArray("beh");
            if (beh != null && beh.length() > 0) v.behavior = pick(beh.optJSONArray((dayNumber() + shift) % beh.length()), L);
        } catch (Exception ignored) { }
        v.relation = relation(v.relationId, L);
        return v;
    }

    static String relation(int r, int L) {
        String[][] R = { { "العلاقة بالله ﷻ", "Relationship with Allah" }, { "العلاقة بالنفس", "Relationship with Self" }, { "العلاقة بالآخرين", "Relationship with Others" } };
        return r >= 1 && r <= 3 ? R[r - 1][L] : "";
    }

    private static String pick(JSONArray p, int L) {
        if (p == null) return "";
        String s = p.optString(L, "");
        return s.isEmpty() ? p.optString(1 - L, "") : s;
    }
}
